[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ContractPath)
$ErrorActionPreference='Stop'
$repo=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path
$contract=Get-Content -LiteralPath $ContractPath -Raw -Encoding UTF8|ConvertFrom-Json
$errors=[Collections.Generic.List[string]]::new()
function Eq($name,$actual,$expected){if($actual-ne$expected){$errors.Add("$name expected=$expected actual=$actual")}}
function Seq($name,$actual,$expected){if((@($actual)|ConvertTo-Json -Compress -Depth 20)-ne(@($expected)|ConvertTo-Json -Compress -Depth 20)){$errors.Add("$name sequence mismatch")}}
function Load($path){Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json}
$hashes=[ordered]@{
 movementStaticLedger='9BC141E9C2F9AA7A0EF6BADF9B63CED2822F3E5D7AF820382F38803523ED3B99'
 movementSchema='1DBADE5E0EFAC91ED648307C8026B26A4F80BC9A4E3A4F2E80AAED749BFC24F4'
 movementTemplate='122B8555BF25E752AE82958F14188669FCCE6B7FFB9BF4A9307CF1EA0DE9AD5A'
 movementVerifier='299648AED08C07A75B31A0E52D2A59A6AAE35C0B24E7E46CAD0D7452B9B1BCFF'
